import type { PulseCandidate } from '../../src/domain/pulse-reading';

/**
 * SYNTHETIC test fixture. These values are generated by test code; they are
 * not camera measurements and must never be used as live or demo evidence.
 */
export interface SyntheticSegment {
  readonly durationMs: number;
  readonly bpm: number;
  readonly confidence?: number;
  readonly stable?: boolean;
}

export interface SyntheticStream {
  readonly candidates: readonly PulseCandidate[];
  readonly endMs: number;
}

export function syntheticPulseStream(
  startMs: number,
  intervalMs: number,
  segments: readonly SyntheticSegment[],
): SyntheticStream {
  const candidates: PulseCandidate[] = [];
  let t = startMs;
  for (const segment of segments) {
    const end = t + segment.durationMs;
    for (; t < end; t += intervalMs) {
      candidates.push({
        bpm: segment.bpm,
        confidence: segment.confidence ?? 90,
        stable: segment.stable ?? true,
        // SDK time is offset from app time to prove the policy never mixes the two clocks.
        sdkTimestampUs: (t + 1_700_000_000_000) * 1000,
        receivedAtMs: t,
      });
    }
  }
  return { candidates, endMs: t };
}
